  function countryTemplate(c, i) {
    return {
      name:c.name, flag:c.flag, continent:c.continent, x:c.x, y:c.y,
      iso:c.iso, iso2:ISO2_BY_ISO3[c.iso] || c.iso, en:c.en,
      power:c.power,
      resources:{
        oil:Math.round(260+c.power*.55),
        coin:Math.round(420+c.power*.75),
        wheat:Math.round(380+c.power*.45),
        iron:Math.round(220+c.power*.42)
      },
      status:"neutral", relations:0,
      ai:{level:Math.max(1,Math.min(10,Math.round(c.power/120))), aggression:0.35+(i%5)*0.08,
          economy:0.8+(i%4)*0.12}
    };
  }

